document.addEventListener("DOMContentLoaded",()=>{const o=(t,n)=>{try{typeof t=="function"&&t()}catch(r){console.warn(`[Teemous Lab] Warning in ${n}:`,r)}};if(typeof gsap<"u"&&typeof ScrollTrigger<"u")try{gsap.registerPlugin(ScrollTrigger)}catch{}o(initThemeToggle,"ThemeToggle"),o(initLanguageToggle,"LanguageToggle"),o(initMobileMenu,"MobileMenu"),o(initScrollAnimations,"ScrollAnimations"),o(initBackgroundAnimation,"BackgroundAnimation"),o(initScrollProgress,"ScrollProgress"),o(initCardSpotlights,"CardSpotlights"),o(initLiveTelemetry,"LiveTelemetry"),o(initHoverEffects,"HoverEffects"),o(initServicesDirectory,"ServicesDirectory");let e=!1;const i=()=>{e||(e=!0,["scroll","pointerdown","touchstart","keydown"].forEach(t=>{window.removeEventListener(t,i,{passive:!0})}),o(initScrollAnimations,"ScrollAnimations"),o(initBackgroundAnimation,"BackgroundAnimation"),o(initScrollProgress,"ScrollProgress"),o(initCardSpotlights,"CardSpotlights"),o(initLiveTelemetry,"LiveTelemetry"),o(initHoverEffects,"HoverEffects"),o(initServicesDirectory,"ServicesDirectory"),o(initSmmTerminal,"SmmTerminal"),o(initChatbot,"Chatbot"),o(initAuthModal,"AuthModal"),o(initDashboard,"Dashboard"),o(initTopUpModal,"TopUpModal"),o(initPortfolioFilters,"PortfolioFilters"),o(initGalleryToggle,"GalleryToggle"),o(ensureMobileWidgets,"EnsureMobileWidgets"))};["scroll","pointerdown","touchstart","keydown"].forEach(t=>{window.addEventListener(t,i,{passive:!0,once:!0})}),"requestIdleCallback"in window?requestIdleCallback(i,{timeout:3500}):setTimeout(i,2500)});function initScrollProgress(){const o=document.createElement("div");o.className="scroll-progress-container";const e=document.createElement("div");e.className="scroll-progress-bar",o.appendChild(e),document.body.appendChild(o);let i=!1;window.addEventListener("scroll",()=>{i||(requestAnimationFrame(()=>{const t=document.body.scrollTop||document.documentElement.scrollTop,n=document.documentElement.scrollHeight-document.documentElement.clientHeight,r=n>0?t/n*100:0;e.style.width=r+"%",i=!1}),i=!0)},{passive:!0})}function initScrollAnimations() {
    if (typeof gsap === 'undefined') return;

    if (typeof ScrollTrigger !== 'undefined') {
        try { gsap.registerPlugin(ScrollTrigger); } catch(e) {}
    }

    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion) return;

    gsap.defaults({ ease: 'power3.out', duration: 0.85 });

    // 1. Hero Entrance: Masked Line Reveal, H1, Meta Bar, Manifesto & Laser Sweep
    const titleLines = document.querySelectorAll('.title-line');
    const metaBar = document.querySelector('.editorial-meta-bar');
    const manifesto = document.querySelector('.editorial-manifesto-text');
    const ctas = document.querySelectorAll('.editorial-cta-row a, .commission-gate a');
    const hairlines = document.querySelectorAll('.hairline');

    if (titleLines.length > 0) {
        const heroTl = gsap.timeline({ defaults: { ease: 'power4.out' } });

        if (metaBar) {
            heroTl.fromTo(metaBar, { y: -18, opacity: 0 }, { y: 0, opacity: 1, duration: 0.8, ease: 'power3.out' });
        }

        heroTl.fromTo(titleLines, 
            { yPercent: 115, opacity: 0 }, 
            { 
                yPercent: 0, 
                opacity: 1,
                duration: 1.15, 
                stagger: 0.12, 
                ease: 'power4.out',
                onComplete: () => {
                    document.querySelectorAll('.mask-wrap').forEach(w => {
                        w.style.overflow = 'visible';
                    });
                }
            },
            "-=0.5"
        );

        if (manifesto) {
            heroTl.fromTo(manifesto, { y: 15, opacity: 0 }, { y: 0, opacity: 1, duration: 0.7, ease: 'power3.out' }, "-=0.6");
        }
        if (ctas.length > 0) {
            heroTl.fromTo(ctas, { y: 15, opacity: 0 }, { y: 0, opacity: 1, duration: 0.6, stagger: 0.08, ease: 'power3.out' }, "-=0.4");
        }
        if (hairlines.length > 0) {
            heroTl.fromTo(hairlines[0], { scaleX: 0, transformOrigin: 'left center' }, { scaleX: 1, duration: 1.2, ease: 'power3.inOut' }, "-=0.5");
        }
    }

    // 2. SEO Lead Section Reveal
    const seoLead = document.querySelector('.seo-lead-intro');
    if (seoLead && typeof ScrollTrigger !== 'undefined') {
        gsap.fromTo(seoLead,
            { y: 24, opacity: 0 },
            {
                scrollTrigger: {
                    trigger: seoLead,
                    start: 'top 88%',
                    once: true
                },
                y: 0,
                opacity: 1,
                duration: 0.75,
                ease: 'power3.out',
                clearProps: 'transform,opacity,willChange'
            }
        );
    }

    // 3. Editorial Section Headers (H2 + Section Tags + Subtitles Reveal on Scroll)
    const sectionHeaders = document.querySelectorAll('.editorial-section-header');
    if (sectionHeaders.length > 0 && typeof ScrollTrigger !== 'undefined') {
        sectionHeaders.forEach(header => {
            gsap.fromTo(header,
                { y: 24, opacity: 0 },
                {
                    scrollTrigger: {
                        trigger: header,
                        start: 'top 85%',
                        once: true
                    },
                    y: 0,
                    opacity: 1,
                    duration: 0.7,
                    ease: 'power3.out',
                    clearProps: 'transform,opacity,willChange'
                }
            );
        });
    }

    // 4. Lookbook Section: Meng To Architectural Staggered Reveal
    const lookbookSection = document.getElementById('lookbook');
    const lookbookCards = document.querySelectorAll('.lookbook-card');
    if (lookbookSection && lookbookCards.length > 0 && typeof ScrollTrigger !== 'undefined') {
        gsap.fromTo(lookbookCards,
            { y: 30, opacity: 0 },
            {
                scrollTrigger: {
                    trigger: '#lookbook',
                    start: 'top 78%',
                    once: true
                },
                y: 0,
                opacity: 1,
                duration: 0.65,
                stagger: 0.08,
                ease: 'power2.out',
                clearProps: 'transform,opacity,willChange'
            }
        );
    }

    // 5. Systems Section: Staggered Architectural Spectrum Reveal
    const systemsSection = document.getElementById('systems');
    const spectrumCols = document.querySelectorAll('.spectrum-col');
    if (systemsSection && spectrumCols.length > 0 && typeof ScrollTrigger !== 'undefined') {
        gsap.fromTo(spectrumCols,
            { y: 32, opacity: 0 },
            {
                scrollTrigger: {
                    trigger: '#systems',
                    start: 'top 78%',
                    once: true
                },
                y: 0,
                opacity: 1,
                duration: 0.75,
                stagger: 0.1,
                ease: 'power3.out',
                clearProps: 'transform,opacity,willChange'
            }
        );
    }

    // 6. Commission Section Reveal
    const commissionSection = document.getElementById('commission');
    if (commissionSection && typeof ScrollTrigger !== 'undefined') {
        const commElements = commissionSection.querySelectorAll('.commission-title, .commission-text, .commission-gate');
        if (commElements.length > 0) {
            gsap.fromTo(commElements,
                { y: 22, opacity: 0 },
                {
                    scrollTrigger: {
                        trigger: '#commission',
                        start: 'top 85%',
                        once: true
                    },
                    y: 0,
                    opacity: 1,
                    duration: 0.7,
                    stagger: 0.1,
                    ease: 'power3.out',
                    clearProps: 'transform,opacity,willChange'
                }
            );
        }
    }

    // 7. FAQ Section Reveal
    const faqSection = document.getElementById('faq');
    const faqItems = document.querySelectorAll('.faq-item');
    if (faqSection && faqItems.length > 0 && typeof ScrollTrigger !== 'undefined') {
        gsap.fromTo(faqItems,
            { y: 20, opacity: 0 },
            {
                scrollTrigger: {
                    trigger: '#faq',
                    start: 'top 85%',
                    once: true
                },
                y: 0,
                opacity: 1,
                duration: 0.5,
                stagger: 0.07,
                ease: 'power2.out',
                clearProps: 'transform,opacity,willChange'
            }
        );
    }

    // 8. Magnetic Button Physics (Desktop Only)
    if (!window.matchMedia('(pointer: coarse)').matches) {
        ctas.forEach(btn => {
            const xTo = gsap.quickTo(btn, 'x', { duration: 0.4, ease: 'power3.out' });
            const yTo = gsap.quickTo(btn, 'y', { duration: 0.4, ease: 'power3.out' });
            let rect = null;

            btn.addEventListener('pointerenter', () => {
                rect = btn.getBoundingClientRect();
            });

            btn.addEventListener('pointermove', (e) => {
                if (!rect) rect = btn.getBoundingClientRect();
                const strength = 0.28;
                const x = (e.clientX - rect.left - rect.width / 2) * strength;
                const y = (e.clientY - rect.top - rect.height / 2) * strength;
                xTo(x);
                yTo(y);
            }, { passive: true });

            btn.addEventListener('pointerleave', () => {
                rect = null;
                xTo(0);
                yTo(0);
            });
        });
    }

    // 9. Portfolio / Activities Grid (if present)
    const portfolioTriggerId = document.getElementById('portfolio') ? '#portfolio' : '#activities';
    const portfolioTrigger = document.querySelector(portfolioTriggerId);
    const projectCards = document.querySelectorAll('.project-card');

    if (portfolioTrigger && projectCards.length > 0 && typeof ScrollTrigger !== 'undefined') {
        gsap.fromTo(projectCards,
            { y: 40, opacity: 0 },
            {
                scrollTrigger: {
                    trigger: portfolioTrigger,
                    start: 'top 85%',
                    once: true
                },
                duration: 0.8,
                y: 0,
                opacity: 1,
                stagger: 0.12,
                ease: 'power3.out',
                clearProps: 'transform,willChange'
            }
        );
    }

    // 10. Safety fallback
    setTimeout(() => {
        const checkElements = document.querySelectorAll('.editorial-section-header, .lookbook-card, .spectrum-col, .commission-title');
        checkElements.forEach(el => {
            if (window.getComputedStyle(el).opacity === '0') {
                gsap.to(el, { opacity: 1, y: 0, duration: 0.4, clearProps: 'all' });
            }
        });
    }, 2500);
}

function initBackgroundAnimation() {
    if (window.location.pathname.includes('/user')) return;

    const canvas = document.getElementById('bg-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        return;
    }

    let width = 0, height = 0;
    let particles = [];
    let mouse = { x: null, y: null, targetX: null, targetY: null };
    let isVisible = !document.hidden;
    let animId = null;
    let lastTime = 0;
    const targetFpsInterval = 1000 / 60;

    window.addEventListener('mousemove', (e) => {
        mouse.targetX = e.clientX;
        mouse.targetY = e.clientY;
        if (mouse.x === null) {
            mouse.x = e.clientX;
            mouse.y = e.clientY;
        }
    }, { passive: true });

    window.addEventListener('touchmove', (e) => {
        if (e.touches && e.touches.length > 0) {
            mouse.targetX = e.touches[0].clientX;
            mouse.targetY = e.touches[0].clientY;
            if (mouse.x === null) {
                mouse.x = mouse.targetX;
                mouse.y = mouse.targetY;
            }
        }
    }, { passive: true });

    function resize() {
        width = window.innerWidth;
        height = window.innerHeight;
        canvas.width = width;
        canvas.height = height;
        initParticles();
    }
    window.addEventListener('resize', resize, { passive: true });

    class Particle {
        constructor() {
            this.x = Math.random() * width;
            this.y = Math.random() * height;
            this.size = Math.random() * 1.8 + 1.0;
            this.baseX = this.x;
            this.baseY = this.y;
            this.vx = (Math.random() - 0.5) * 0.45;
            this.vy = (Math.random() - 0.5) * 0.45;
            this.density = (Math.random() * 20) + 1;
            // 0 = Cyan, 1 = Purple, 2 = Pink
            this.colorType = Math.floor(Math.random() * 3);
        }

        update() {
            this.baseX += this.vx;
            this.baseY += this.vy;

            if (this.baseX < 0) this.baseX = width;
            if (this.baseX > width) this.baseX = 0;
            if (this.baseY < 0) this.baseY = height;
            if (this.baseY > height) this.baseY = 0;

            if (mouse.x != null) {
                const dx = mouse.x - width / 2;
                const dy = mouse.y - height / 2;
                const factor = (30 / this.density) * 0.05;
                const targetX = this.baseX - (dx * factor);
                const targetY = this.baseY - (dy * factor);

                this.x += (targetX - this.x) * 0.06;
                this.y += (targetY - this.y) * 0.06;
            } else {
                this.x = this.baseX;
                this.y = this.baseY;
            }
        }
    }

    function initParticles() {
        particles = [];
        const isMobile = width < 768;
        const maxParticles = isMobile ? 38 : 72;
        const baseDensity = isMobile ? 22000 : 18000;
        const numParticles = Math.min(maxParticles, Math.max(20, Math.floor((width * height) / baseDensity)));
        for (let i = 0; i < numParticles; i++) {
            particles.push(new Particle());
        }
    }

    function drawParticlesAndConnections(isLight) {
        const maxDistSq = 14000; // ~118px threshold

        // 1. Draw connection network
        for (let a = 0; a < particles.length; a++) {
            const pa = particles[a];
            for (let b = a + 1; b < particles.length; b++) {
                const pb = particles[b];
                const dx = pa.x - pb.x;
                const dy = pa.y - pb.y;
                const distSq = dx * dx + dy * dy;

                if (distSq < maxDistSq) {
                    const alpha = (1 - distSq / maxDistSq) * (isLight ? 0.22 : 0.26);
                    ctx.beginPath();
                    ctx.moveTo(pa.x, pa.y);
                    ctx.lineTo(pb.x, pb.y);
                    ctx.strokeStyle = isLight 
                        ? `rgba(2, 132, 199, ${alpha})` 
                        : `rgba(0, 240, 255, ${alpha})`;
                    ctx.lineWidth = 0.8;
                    ctx.stroke();
                }
            }
        }

        // 2. Batch Cyan particles
        ctx.fillStyle = isLight ? 'rgba(2, 132, 199, 0.65)' : 'rgba(0, 240, 255, 0.75)';
        ctx.beginPath();
        for (let i = 0; i < particles.length; i++) {
            const p = particles[i];
            if (p.colorType === 0) {
                ctx.moveTo(p.x + p.size, p.y);
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            }
        }
        ctx.fill();

        // 3. Batch Purple particles
        ctx.fillStyle = isLight ? 'rgba(109, 40, 217, 0.65)' : 'rgba(156, 39, 176, 0.75)';
        ctx.beginPath();
        for (let i = 0; i < particles.length; i++) {
            const p = particles[i];
            if (p.colorType === 1) {
                ctx.moveTo(p.x + p.size, p.y);
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            }
        }
        ctx.fill();

        // 4. Batch Pink particles
        ctx.fillStyle = isLight ? 'rgba(219, 39, 119, 0.65)' : 'rgba(233, 30, 99, 0.75)';
        ctx.beginPath();
        for (let i = 0; i < particles.length; i++) {
            const p = particles[i];
            if (p.colorType === 2) {
                ctx.moveTo(p.x + p.size, p.y);
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            }
        }
        ctx.fill();
    }

    function animate(now) {
        if (!isVisible) return;
        animId = requestAnimationFrame(animate);

        const delta = now - lastTime;
        if (delta < targetFpsInterval - 2) return;
        lastTime = now - (delta % targetFpsInterval);

        ctx.clearRect(0, 0, width, height);

        if (mouse.targetX !== null) {
            mouse.x += (mouse.targetX - mouse.x) * 0.08;
            mouse.y += (mouse.targetY - mouse.y) * 0.08;
        }

        const isLight = document.documentElement.classList.contains('light-mode') || document.body.classList.contains('light-mode');

        for (let i = 0; i < particles.length; i++) {
            particles[i].update();
        }

        drawParticlesAndConnections(isLight);
    }

    document.addEventListener('visibilitychange', () => {
        if (document.hidden) {
            isVisible = false;
            if (animId) cancelAnimationFrame(animId);
        } else {
            isVisible = true;
            lastTime = performance.now();
            animId = requestAnimationFrame(animate);
        }
    });

    resize();
    lastTime = performance.now();
    animId = requestAnimationFrame(animate);
}

